refentry.refsect1:
&reftitle.parameters;
name
Название конфигурации, которую требуется исследовать; применяют ту же точечную нотацию, что и в методе Yaconf::get.

  &reftitle.examples;

   Пример использования метода Yaconf::__debug_info


<?php
// предполагаем, что файл app.ini содержит name="shop"
var_dump(Yaconf::__debug_info("app.name"));
/*
array(4) {
  ["key"]=>
  string(8) "app.name"
  ["address"]=>
  string(14) "0x7f8b1c0a3d20"
  ["val"]=>
  string(4) "shop"
  ["changed"]=>
  bool(false)
}
*/

var_dump(Yaconf::__debug_info("app.missing")); // NULL
?>
